type Entry = Omit<MortgageConcept, 'branch' | 'topic'>;
function entry(input: Entry): MortgageConcept {
  const topic = expansion_topics.find(t => t.concepts.includes(input.id));
  if (!topic) throw new Error(`Missing expansion topic: ${input.id}`);
  return { ...input, branch: topic.branch, topic: topic.id };
}

