export const expansion_paths = [
  { id: 'rates_to_mortgages', title: 'Why a rate cut need not lower mortgage rates', description: 'Separate policy expectations, term premium and the primary mortgage spread.', premise: 'Trace the components of rate transmission. The steps organize an explanation; they do not predict the next market move.', steps: ['policy_rate', 'policy_expectations', 'term_premium', 'current_coupon', 'primary_secondary_spread', 'affordability'], explanations: ['Start with the current policy setting and what was already anticipated.', 'Ask how the expected future path changed relative to expectations.', 'Allow compensation for holding long-duration risk to move independently.', 'Read the secondary mortgage yield together with option and demand effects.', 'Add the economics between the secondary market and the borrower quote.', 'Translate the offered loan terms into the borrower’s payment constraint.'], boundary: 'Term premium, option cost, lender capacity and borrower terms can offset the policy move. No deterministic rate forecast follows from this path.' },
  { id: 'curve_to_hedge', title: 'A duration match can still miss the curve', description: 'Follow a steepener from key-rate exposure to the hedge instrument.', premise: 'This is a risk-analysis workflow: matching one scalar measure does not match every scenario.', steps: ['curve_slope', 'key_rate', 'duration', 'convexity', 'interest_rate_swap', 'swaption', 'basis_risk'], explanations: ['Name both tenor moves instead of saying only “rates rose”.', 'Locate exposure along the curve, including the belly and wings.', 'Check what the aggregate duration holds fixed.', 'Allow mortgage duration to change when expected principal timing changes.', 'Use a swap’s direction and sensitivity to offset part of first-order rate risk.', 'Consider how option exposure differs by expiry, tenor and strike.', 'Keep remaining curve, financing, spread and model mismatch explicit.'], boundary: 'An option or swap does not eliminate borrower behavior, credit or liquidity risk. This is an explanatory sequence, not a recommended trading position.' },
  { id: 'floating_rate_clock', title: 'The same SOFR name can hide different cash flows', description: 'Walk from the benchmark through observation rules to residual hedge basis.', premise: 'Compare two contracts by reading their payment definitions before comparing their rates.', steps: ['sofr', 'term_overnight', 'reset_payment_dates', 'observation_conventions', 'dual_curve', 'basis_risk'], explanations: ['Identify the administered overnight benchmark.', 'Distinguish a forward-looking term fixing from compounded overnight observations.', 'Place observation, reset, accrual and payment on separate dates.', 'Read lookback, weighting, lockout, calendars and payment lag.', 'Separate the projected coupon index from the discounting framework.', 'Identify the mismatch left between the security and its hedge.'], boundary: 'The named reference rate alone does not establish cash-flow equivalence. Always use the actual contractual convention.' },
  { id: 'rmbs_label_decoder', title: 'Decode an RMBS pipeline label', description: 'Size, credit, occupancy, regulation and lien position are different axes.', premise: 'These are classification questions, not a causal chain or a hierarchy from safer to riskier.', steps: ['conforming_jumbo', 'prime_jumbo', 'investor_mortgages', 'non_qm', 'second_lien', 'heloc', 'cltv'], explanations: ['Check loan size and eligibility without inferring the security guarantee.', 'Read prime as a credit and underwriting segment, not a guarantee.', 'Identify occupancy and the actual income-verification method.', 'Separate QM status from credit quality and regulatory coverage.', 'Read property-lien priority separately from tranche priority.', 'Distinguish a credit line’s draw mechanics from a closed-end loan.', 'Count additional liens and undrawn credit commitments under the stated convention.'], boundary: 'A short newsletter label is an entry point. Deal documents, collateral disclosures and operative rules determine the actual terms.' },
  { id: 'cre_workout_to_tranche', title: 'From a troubled property exit to tranche cash flows', description: 'Follow maturity pressure through servicing, advancing and modified timing.', premise: 'This path lists possible transmission channels. A distressed loan need not experience every step.', steps: ['refinance_risk', 'extension_options', 'special_servicing', 'appraisal_reduction', 'servicing_advances', 'loan_modification', 'collateral_tranche_cashflows'], explanations: ['Compare repayment due with realistic refinancing and property-sale capacity.', 'Check whether contractual extension conditions can actually be met.', 'Read the transfer trigger and the special servicer’s authority.', 'Distinguish appraisal-based adjustments from final realized losses.', 'Identify which collections are bridged and how advances are reimbursed.', 'Rebuild amount and timing assumptions from the executed workout terms.', 'Apply the actual waterfall to determine each claim’s receipts.'], boundary: 'Transfer, appraisal reduction, modification and liquidation are different events. The servicing agreement and executed terms control each channel.' },
  { id: 'headline_to_evidence', title: 'Turn a newsletter headline into an analytical question', description: 'Read deal stage, data, score models and assumptions before judging value.', premise: 'An evidence workflow for new issuance and policy coverage, using original concepts and public references.', steps: ['deal_lifecycle', 'reg_ab', 'credit_score_models', 'collateral_stratification', 'scenario_analysis', 'spread_conventions'], explanations: ['Identify what was marketed, priced or settled and the reporting cut-off.', 'Determine which disclosures exist and whether a policy change is actually effective.', 'Check that reported scores use comparable model versions and dates.', 'Separate collateral composition from an average headline statistic.', 'State forward assumptions and alternatives without presenting history as a forecast.', 'Align curve, option treatment, timing and units before comparing quoted spreads.'], boundary: 'No headline or label replaces transaction documents. A missing source stays an open question rather than becoming an invented fact.' },
];
